import sys

def parse_json(text: str) -> object:
    sys.set_int_max_str_digits(0)
    n = len(text)
    i = 0

    def skip_ws():
        nonlocal i
        while i < n and text[i] in ' \t\n\r':
            i += 1

    def parse_str():
        nonlocal i
        i += 1
        parts = []
        while i < n:
            ch = text[i]
            if ch == '"':
                i += 1
                return ''.join(parts)
            if ch == '\\':
                i += 1
                if i >= n:
                    raise ValueError
                ch2 = text[i]
                if ch2 == '"':
                    parts.append('"'); i += 1
                elif ch2 == '\\':
                    parts.append('\\'); i += 1
                elif ch2 == '/':
                    parts.append('/'); i += 1
                elif ch2 == 'b':
                    parts.append('\b'); i += 1
                elif ch2 == 'f':
                    parts.append('\f'); i += 1
                elif ch2 == 'n':
                    parts.append('\n'); i += 1
                elif ch2 == 'r':
                    parts.append('\r'); i += 1
                elif ch2 == 't':
                    parts.append('\t'); i += 1
                elif ch2 == 'u':
                    i += 1
                    if i + 4 > n:
                        raise ValueError
                    h = text[i:i+4]
                    for c in h:
                        if c not in '0123456789abcdefABCDEF':
                            raise ValueError
                    cp = int(h, 16)
                    i += 4
                    if 0xD800 <= cp <= 0xDBFF:
                        if i + 6 > n or text[i] != '\\' or text[i+1] != 'u':
                            raise ValueError
                        h2 = text[i+2:i+6]
                        for c in h2:
                            if c not in '0123456789abcdefABCDEF':
                                raise ValueError
                        cp2 = int(h2, 16)
                        if not (0xDC00 <= cp2 <= 0xDFFF):
                            raise ValueError
                        parts.append(chr(0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00)))
                        i += 6
                    elif 0xDC00 <= cp <= 0xDFFF:
                        raise ValueError
                    else:
                        parts.append(chr(cp))
                else:
                    raise ValueError
            elif ord(ch) < 0x20:
                raise ValueError
            else:
                parts.append(ch)
                i += 1
        raise ValueError

    def parse_num():
        nonlocal i
        start = i
        if i < n and text[i] == '-':
            i += 1
        if i >= n:
            raise ValueError
        if text[i] == '0':
            i += 1
        elif '1' <= text[i] <= '9':
            i += 1
            while i < n and '0' <= text[i] <= '9':
                i += 1
        else:
            raise ValueError
        is_float = False
        if i < n and text[i] == '.':
            i += 1
            if i >= n or not ('0' <= text[i] <= '9'):
                raise ValueError
            while i < n and '0' <= text[i] <= '9':
                i += 1
            is_float = True
        if i < n and text[i] in 'eE':
            i += 1
            if i < n and text[i] in '+-':
                i += 1
            if i >= n or not ('0' <= text[i] <= '9'):
                raise ValueError
            while i < n and '0' <= text[i] <= '9':
                i += 1
            is_float = True
        num_str = text[start:i]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    skip_ws()
    if i >= n:
        raise ValueError

    stack = []

    while True:
        skip_ws()
        if i >= n:
            raise ValueError
        ch = text[i]

        if ch == '{':
            stack.append(['dict', {}, 'start'])
            i += 1
            skip_ws()
            if i >= n:
                raise ValueError
            if text[i] == '}':
                i += 1
                value = stack[-1][1]
                stack.pop()
            else:
                if text[i] != '"':
                    raise ValueError
                key = parse_str()
                stack[-1][3] = key
                skip_ws()
                if i >= n or text[i] != ':':
                    raise ValueError
                i += 1
                continue
        elif ch == '[':
            stack.append(['list', [], 'start'])
            i += 1
            skip_ws()
            if i >= n:
                raise ValueError
            if text[i] == ']':
                i += 1
                value = stack[-1][1]
                stack.pop()
            else:
                continue
        elif ch == '"':
            value = parse_str()
        elif ch == '-' or '0' <= ch <= '9':
            value = parse_num()
        elif ch == 't':
            if i + 4 <= n and text[i:i+4] == 'true':
                value = True; i += 4
            else:
                raise ValueError
        elif ch == 'f':
            if i + 5 <= n and text[i:i+5] == 'false':
                value = False; i += 5
            else:
                raise ValueError
        elif ch == 'n':
            if i + 4 <= n and text[i:i+4] == 'null':
                value = None; i += 4
            else:
                raise ValueError
        else:
            raise ValueError

        while True:
            if not stack:
                skip_ws()
                if i >= n:
                    return value
                raise ValueError
            frame = stack[-1]
            if frame[0] == 'list':
                frame[1].append(value)
                frame[2] = 'after_value'
                skip_ws()
                if i >= n:
                    raise ValueError
                ch = text[i]
                if ch == ']':
                    i += 1
                    value = frame[1]
                    stack.pop()
                    continue
                elif ch == ',':
                    i += 1
                    break
                else:
                    raise ValueError
            else:
                key = frame[3]
                if key in frame[1]:
                    raise ValueError
                frame[1][key] = value
                frame[2] = 'after_value'
                skip_ws()
                if i >= n:
                    raise ValueError
                ch = text[i]
                if ch == '}':
                    i += 1
                    value = frame[1]
                    stack.pop()
                    continue
                elif ch == ',':
                    i += 1
                    skip_ws()
                    if i >= n or text[i] != '"':
                        raise ValueError
                    key = parse_str()
                    frame[3] = key
                    skip_ws()
                    if i >= n or text[i] != ':':
                        raise ValueError
                    i += 1
                    break
                else:
                    raise ValueError
